ern:NewReleaseMessage.PartyList:
{{~ for asset in album.asset_list ~}}
{{~ if for.first ~}}
{{~ for party in asset.users_party_list ~}}

	P{{ party.name | string.replace " " "" }}

		{{ party.name }}
		{{ party.name }}

	{{~ has_internal  = party.internal_id && party.internal_id != "" ~}}
	{{~ has_spotify   = party.spotify_id  && party.spotify_id  != "" ~}}
	{{~ has_facebook  = party.facebook_id && party.facebook_id != "" ~}}
	{{~ has_instagram = party.instagram   && party.instagram   != "" ~}}
	{{~ if has_internal || has_spotify || has_facebook ~}}

		{{~ if has_internal ~}}
		{{ party.internal_id }}
		{{~ end ~}}

	{{~ end ~}}
	{{~ if has_facebook ~}}
	{{ (party.instagram | string.downcase) == "new" ? "NEW" : "https://www.facebook.com/" + party.facebook_id }}
	{{~ end ~}}
	{{~ if has_instagram ~}}
	{{ (party.instagram | string.downcase) == "new" ? "NEW" : "https://www.instagram.com/" + party.instagram }}
	{{~ end ~}}

{{~ end ~}}
{{~ end ~}}
{{~ end ~}}

	PGlobal

		{{ album.label_name }}

